from collections import deque

def bfs_labels(X,Y,base,labA,labB,ring):
 h,w=X.shape; INF=9999; dist={labA:np.full((h,w),INF),labB:np.full((h,w),INF)}
 for lab in (labA,labB):
  q=deque()
  for r,c in np.argwhere(X==base):
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
    if 0<=rr<h and 0<=cc<w and X[rr,cc]==lab:
     dist[lab][r,c]=0;q.append((r,c));break
  while q:
   r,c=q.popleft()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
    if 0<=rr<h and 0<=cc<w and X[rr,cc]==base and dist[lab][rr,cc]>dist[lab][r,c]+1:
     dist[lab][rr,cc]=dist[lab][r,c]+1;q.append((rr,cc))
